import openpyxl, os, json
path='/root/data/workbook.xlsx'
print('exists', os.path.exists(path), 'size', os.path.getsize(path) if os.path.exists(path) else None)
wb = openpyxl.load_workbook(path, data_only=False)
print('Sheet names:', wb.sheetnames)
ws=wb['Task']

def cell_range_vals(addr):
    vals=[]
    for row in ws[addr]:
        vals.append([c.coordinate+': '+repr(c.value) for c in row])
    return vals
print('\nTask D12:D17 block 1:')
for row in cell_range_vals('D12:D17'): print(row)
print('\nTask D19:D24 block 2:')
for row in cell_range_vals('D19:D24'): print(row)
print('\nTask D26:D31 block 3:')
for row in cell_range_vals('D26:D31'): print(row)
print('\nTask row 10 H-L years:')
print([ws.cell(10,c).coordinate+': '+repr(ws.cell(10,c).value) for c in range(8,13)])
print('\nTask labels/ports H35:H40 and D35:D40:')
for r in range(35,41):
    print(f'row {r}: D={ws.cell(r,4).value!r}, H={ws.cell(r,8).value!r}')
print('\nTask stat labels H42:H47 and D42:D47:')
for r in range(42,48):
    print(f'row {r}: D={ws.cell(r,4).value!r}, H={ws.cell(r,8).value!r}')
print('\nTask D50 and nearby H50 row labels/values:')
for c in range(1,13):
    v=ws.cell(50,c).value
    if v is not None:
        print(ws.cell(50,c).coordinate, repr(v))
for r in range(48,52):
    vals=[]
    for c in range(1,13):
        v=ws.cell(r,c).value
        if v is not None:
            vals.append(f'{ws.cell(r,c).coordinate}={v!r}')
    if vals: print('row',r, vals)

wd=wb['Data']
print('\nData rows 21-38, all populated columns:')
for r in range(21,39):
    vals=[]
    for c in range(1, wd.max_column+1):
        v=wd.cell(r,c).value
        if v is not None:
            vals.append(f'{wd.cell(r,c).coordinate}={v!r}')
    print('row', r, ' | '.join(vals))
print('\nData dimensions', wd.max_row, wd.max_column)
